/******************CREATE INSTALLATION PROCEDURE********************/ CREATE PROCEDURE "DA_CA_INSTALL" (IN SchemaName VARCHAR(100)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     DECLARE ROWCNT INTEGER;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_DATA_TBL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN     EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_NN_DATA_TBL_T';      END IF;     EXECUTE IMMEDIATE 'CREATE TYPE DA_CA_PAL_NN_DATA_TBL_T AS TABLE ("COLUMNNAME" VARCHAR (100), "COLUMNTYPE" VARCHAR (100), "ISTRAIN" INTEGER, "ISPREDICT" INTEGER)';     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_MODEL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_NN_MODEL_T';      END IF;     EXECUTE IMMEDIATE 'CREATE TYPE DA_CA_PAL_NN_MODEL_T AS TABLE("NAME" VARCHAR(100), "MODEL" CLOB)';     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LT_DATA_TBL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN     EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LT_DATA_TBL_T';      END IF;     EXECUTE IMMEDIATE 'CREATE TYPE DA_CA_PAL_LT_DATA_TBL_T AS TABLE ("COLUMNNAME" VARCHAR (100), "COLUMNTYPE" VARCHAR (100), "ISTRAIN" INTEGER, "ISPREDICT" INTEGER)';     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LT_PMMLMODEL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LT_PMMLMODEL_T';      END IF;     EXECUTE IMMEDIATE 'CREATE TYPE DA_CA_PAL_LT_PMMLMODEL_T AS TABLE("ID" INTEGER, "PMMLMODEL" VARCHAR(5000))';     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_CONTROL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_CONTROL_T';      END IF;     EXECUTE IMMEDIATE 'CREATE TYPE DA_CA_PAL_CONTROL_T AS TABLE("NAME" VARCHAR(100), "INTARGS" INTEGER, "DOUBLEARGS" DOUBLE, "STRINGARGS" VARCHAR(100))'; END
